export const inputNames=['Hunger','Fatigue','Loneliness','Ambition','Threat','Curiosity','Low funds','Empathy','Caution','Health risk','Food supply','Attachment'];
export const actionNames=['Eating','Resting','Socializing','Working','Defending','Learning'];
export const shape=[12,10,8,6];
export function createBrain(id){let seed=id+711;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};const weights=shape.slice(1).map((size,l)=>Array.from({length:size},(_,j)=>Array.from({length:shape[l]},(_,i)=>(rand()-.5)*.18+(i===j?1.6:0))));weights[2][3][3]=1.5;weights[2][3][0]=-.6;weights[2][3][1]=-.6;weights[2][3][2]=-.4;return {weights,biases:shape.slice(1).map(n=>Array(n).fill(-.15)),updates:0,reward:0,baseline:0,history:[],trace:null};}
export function infer(c,world){const b=c.brain??=createBrain(c.id);const inputs=[1-c.hunger/100,1-c.energy/100,1-c.social/100,c.ambition/100,world.tension/100,.25+(c.age<18?.65:.1),1-Math.min(c.wealth/200,1),c.empathy/100,c.caution/100,1-c.health/100,Math.min(world.food/100,1),c.partner===null?.2:.8];const layers=[inputs];for(let l=0;l<3;l++){const v=b.weights[l].map((row,j)=>row.reduce((s,w,i)=>s+w*layers[l][i],b.biases[l][j]));layers.push(l===2?v:v.map(Math.tanh))}const logits=layers[3].slice();const price=1+Math.max(0,(100-world.food)/30);const allowed=[world.food>=1&&(c.wealth>=price||world.treasury>=price),true,true,c.age>=18,world.tension>65&&c.age>=18,c.age<18||c.energy>35];const max=Math.max(...logits.filter((_,i)=>allowed[i]));let p=logits.map((x,i)=>allowed[i]?Math.exp((x-max)*2):0),sum=p.reduce((a,v)=>a+v,0);p=p.map(v=>v/sum);let chosen=p.indexOf(Math.max(...p));if(c.hunger<12&&allowed[0])chosen=0;if(c.energy<10)chosen=1;const trace={layers:[...layers.slice(0,3),p],chosen,allowed,inputs};b.trace=trace;return trace;}
export function learn(c,trace,reward){const b=c.brain;const advantage=reward-b.baseline;b.baseline=.96*b.baseline+.04*reward;let delta=trace.layers[3].map((p,i)=>trace.allowed[i]?((i===trace.chosen?1:0)-p)*advantage:0);const gradients=[];for(let l=2;l>=0;l--){gradients[l]=delta;delta=trace.layers[l].map((v,i)=>b.weights[l].reduce((s,row,j)=>s+row[i]*gradients[l][j],0)*(l?1-v*v:1))}for(let l=0;l<3;l++)for(let j=0;j<b.weights[l].length;j++){b.biases[l][j]=Math.max(-3,Math.min(3,b.biases[l][j]+.025*gradients[l][j]));for(let i=0;i<b.weights[l][j].length;i++)b.weights[l][j][i]=Math.max(-3,Math.min(3,b.weights[l][j][i]+.025*gradients[l][j]*trace.layers[l][i]))}b.updates++;b.reward=reward;b.history.unshift({action:actionNames[trace.chosen],reward});b.history=b.history.slice(0,5);}
export function neuralView(c){const b=c.brain,t=b?.trace;if(!t)return '<p>Gathering sensory signals…</p>';const xs=[38,132,218,315],ys=shape.map(n=>Array.from({length:n},(_,i)=>37+i*220/(n-1)));let svg='<svg viewBox="0 0 354 285" role="img" aria-label="Live neural network: 12 inputs, 10 hidden neurons, 8 hidden neurons, 6 actions">';for(let l=0;l<3;l++)for(let j=0;j<shape[l+1];j++)for(let i=0;i<shape[l];i++){const w=b.weights[l][j][i],a=t.layers[l][i];svg+=`<line x1="${xs[l]}" y1="${ys[l][i]}" x2="${xs[l+1]}" y2="${ys[l+1][j]}" stroke="${w>0?'#31b9a0':'#eb7694'}" opacity="${Math.min(.8,.08+Math.abs(w*a)*.25)}" stroke-width="${Math.abs(w)>.8?1.4:.5}"/>`}for(let l=0;l<4;l++){svg+=`<text x="${xs[l]}" y="14" text-anchor="middle">${['SENSE','ENCODE','DRIVE','ACT'][l]}</text>`;for(let i=0;i<shape[l];i++){const a=t.layers[l][i],name=l===0?inputNames[i]:l===3?actionNames[i]:`Layer ${l} neuron ${i+1}`;svg+=`<circle cx="${xs[l]}" cy="${ys[l][i]}" r="${l===3&&t.chosen===i?8:5}" fill="${a>.45?'#ffcc55':a>0?'#65d8b9':'#b2bfd0'}" stroke="#273956" stroke-width="1.5"><title>${name}: ${a.toFixed(3)}</title></circle>`}}svg+='</svg>';return `<div class="neural-meta">12 → 10 → 8 → 6 <span>248 connections · ${b.updates} updates</span></div>${svg}<div class="net-legend"><span>● Activation</span><span>━ Excitatory</span><span>━ Inhibitory</span></div><div class="signals">${inputNames.map((name,i)=>`<span>${name}<b>${Math.round(t.inputs[i]*100)}%</b></span>`).join('')}</div><h3>ACTION PROBABILITIES</h3>${actionNames.map((name,i)=>`<div class="prob ${i===t.chosen?'chosen':''}"><span>${i===t.chosen?'▶ ':''}${name}</span><meter min="0" max="1" value="${t.layers[3][i]}"></meter><b>${Math.round(t.layers[3][i]*100)}%</b></div>`).join('')}<p class="brain-note">A real, small neural policy. Each citizen has unique weights. Outcomes update all three layers using reward feedback. Survival overrides protect critical needs. Hover a neuron for its activation.</p><div class="reward">LAST REWARD <b>${b.reward>=0?'+':''}${b.reward.toFixed(3)}</b> · LEARNING RATE 0.025</div>`;}
